      ,('ar.use_cd', '건축물 주용도', '001', '001001', NULL, '단독주택', '단독주택', NULL)
      ,('ar.use_cd', '건축물 주용도', '001', '001002', NULL, '단독주택', '다중주택', '다음의 요건을 모두 갖춘 주택을 말한다. 1) 학생 또는 직장인 등 여러 사람이 장기간 거주할 수 있는 구조로 되어 있는 것 2) 독립된 주거의 형태를 갖추지 아니한 것(각 실별로 욕실은 설치할 수 있으나, 취사시설은 설치하지 아니한 것을 말한다. 이하 같다) 3) 연면적이 330제곱미터 이하이고 층수가 3층 이하인 것')
      ,('ar.use_cd', '건축물 주용도', '001', '001003', NULL, '단독주택', '다가구주택', '다음의 요건을 모두 갖춘 주택으로서 공동주택에 해당하지 아니하는 것을 말한다. 1) 주택으로 쓰는 층수(지하층은 제외한다)가 3개 층 이하일 것. 다만, 1층의 바닥면적 2분의 1 이상을 필로티 구조로 하여 주차장으로 사용하고 나머지 부분을 주택 외의 용도로 쓰는 경우에는 해당 층을 주택의 층수에서 제외한다. 2) 1개 동의 주택으로 쓰이는 바닥면적(부설 주차장 면적은 제외한다. 이하 같다)의 합계가 660제곱미터 이하일 것 3) 19세대 이하가 거주할 수 있을 것')
      ,('ar.use_cd', '건축물 주용도', '001', '001004', NULL, '단독주택', '공관(公館)', NULL)
      ,('ar.use_cd', '건축물 주용도', '001', NULL, NULL, '단독주택', NULL, '단독주택의 형태를 갖춘 가정어린이집·공동생활가정·지역아동센터 및 노인복지시설(노인복지주택은 제외한다)을 포함한다')
      ,('ar.use_cd', '건축물 주용도', '002', '002001', NULL, '공동주택', '아파트', '주택으로 쓰는 층수가 5개 층 이상인 주택')
      ,('ar.use_cd', '건축물 주용도', '002', '002002', NULL, '공동주택', '연립주택', '주택으로 쓰는 1개 동의 바닥면적(2개 이상의 동을 지하주차장으로 연결하는 경우에는 각각의 동으로 본다) 합계가 660제곱미터를 초과하고, 층수가 4개 층 이하인 주택')
      ,('ar.use_cd', '건축물 주용도', '002', '002003', NULL, '공동주택', '다세대주택', '주택으로 쓰는 1개 동의 바닥면적 합계가 660제곱미터 이하이고, 층수가 4개 층 이하인 주택(2개 이상의 동을 지하주차장으로 연결하는 경우에는 각각의 동으로 본다)')
      ,('ar.use_cd', '건축물 주용도', '002', '002004', NULL, '공동주택', '기숙사', '학교 또는 공장 등의 학생 또는 종업원 등을 위하여 쓰는 것으로서 1개 동의 공동취사시설 이용 세대 수가 전체의 50퍼센트 이상인 것(「교육기본법」 제27조제2항에 따른 학생복지주택을 포함한다)')
      ,('ar.use_cd', '건축물 주용도', '002', NULL, NULL, '공동주택', NULL, '공동주택의 형태를 갖춘 가정어린이집·공동생활가정·지역아동센터·노인복지시설(노인복지주택은 제외한다) 및 「주택법 시행령」 제3조제1항에 따른 원룸형 주택을 포함한다. 다만, 가목이나 나목에서 층수를 산정할 때 1층 전부를 필로티 구조로 하여 주차장으로 사용하는 경우에는 필로티 부분을 층수에서 제외하고, 다목에서 층수를 산정할 때 1층의 바닥면적 2분의 1 이상을 필로티 구조로 하여 주차장으로 사용하고 나머지 부분을 주택 외의 용도로 쓰는 경우에는 해당 층을 주택의 층수에서 제외하며, 가목부터 라목까지의 규정')
      ,('ar.use_cd', '건축물 주용도', '003', '003001', NULL, '제1종 근린생활시설', '소매점', '식품·잡화·의류·완구·서적·건축자재·의약품·의료기기 등 일용품을 판매하는 소매점으로서 같은 건축물(하나의 대지에 두 동 이상의 건축물이 있는 경우에는 이를 같은 건축물로 본다. 이하 같다)에 해당 용도로 쓰는 바닥면적의 합계가 1천 제곱미터 미만인 것')
      ,('ar.use_cd', '건축물 주용도', '003', '003002', NULL, '제1종 근린생활시설', '휴게음식점, 제과점 등', '휴게음식점, 제과점 등 음료·차(茶)·음식·빵·떡·과자 등을 조리하거나 제조하여 판매하는 시설(제4호너목 또는 제17호에 해당하는 것은 제외한다)로서 같은 건축물에 해당 용도로 쓰는 바닥면적의 합계가 300제곱미터 미만인 것')
