      ,('gam_reason_cd', '감리비대상 사유', '003', NULL, NULL, '제94조제1항 각 호의 기관 및「지방공기업법」에 따른 지방공사가 시행하는 공사로서 해당 기관 또는 공사의 소속 직원(건설사업관리를 수행하는 건설기술자를 포함한다)이 제60조에 따른 건설사업관리기술자의 배치기준에 따라 감독 업무를 수행하는 공사', NULL, NULL)
